<?php declare(strict_types=1);
use Kulturhus\Native\Shared\Db;
require_once __DIR__.'/free-list-interface-browser-fixture.php';
$profiles=[];$cases=[];$unlinked=[];$selected=getenv('DVM_CREDIT_REFUND_CASE');
foreach(['front','direct']as$app)foreach([true,false]as$js)foreach(['de','en']as$locale){
    $name=$app.'-'.($js?'js':'nojs').'-'.$locale;if($selected!==false&&$selected!==$name)continue;$profiles[]=compact('name','app','js','locale');
    foreach(['person','organisation']as$kind){$source=($f['make'])($kind,true);$cases[]=['profile'=>$name,'kind'=>$kind,'invoice'=>$source['invoice'],'credit'=>$source['credit'],'entry'=>$source['creditEntry'],'parent_entry'=>$source['entry'],'contact'=>$source['contact'],'mode'=>$kind==='person'?'standard':'instant'];}
    $source=($f['make'])('person',true,false);$unlinked[]=['profile'=>$name,'credit'=>$source['credit'],'entry'=>$source['creditEntry']];
}
if(!$profiles)throw new RuntimeException('Known owned credit refund browser profile required.');
$browser=ownFreeListInterfaceBrowser($db,['profiles'=>$profiles,'cases'=>$cases,'unlinked'=>$unlinked,'account'=>$f['account'],'today'=>$f['today'],'date'=>$f['date']]);$fixture=$browser['input'];
foreach([$f['actor'],$f['reader']]as$actor){$access=(new \Kulturhus\Native\Integration\ManagerBridge($db,$actor,'native',static fn()=>null))->access();(new \Kulturhus\Native\Language\Catalog($db,$access))->select('de');}
$protected=array_values(array_diff($tables,['native_auth_sessions','native_auth_limits','native_language_preferences']));$earlier=[];foreach($protected as$table)$earlier[$table]=$db->query('SELECT * FROM `'.$table.'`')->fetchAll();
$money=$db->query('SELECT * FROM finance_transactions ORDER BY club_id,id')->fetchAll();$entries=$db->query('SELECT * FROM finance_entries ORDER BY club_id,id')->fetchAll();$counts=[];foreach(['finance_transfer_orders','native_settings_requests']as$table)$counts[$table]=(int)$db->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();$preferences=$db->query('SELECT * FROM native_language_preferences ORDER BY club_id,actor_id')->fetchAll();$keys=['bank'=>[$f['path'],$f['keyHash']]];foreach(['auth','private']as$key)$keys[$key]=[$fixture['root'].'/'.$key.'.key',hash_file('sha256',$fixture['root'].'/'.$key.'.key')];
try{
    $process=proc_open(['node',dirname(__DIR__).'/credit-refund-browser.mjs'],[0=>['pipe','r'],1=>STDOUT,2=>STDERR],$pipes);if(!is_resource($process))throw new RuntimeException('Actual credit refund browser required.');fwrite($pipes[0],json_encode($fixture,JSON_THROW_ON_ERROR));fclose($pipes[0]);$check(proc_close($process)===0,'actual credit refund matrix passes through both real application dispatchers');
    $check($db->query('SELECT * FROM finance_transactions ORDER BY club_id,id')->fetchAll()===$money&&$db->query('SELECT * FROM finance_entries ORDER BY club_id,id')->fetchAll()===$entries,'all actual browser preparations approvals and exports preserve every whole money movement and financial entry');
    foreach($earlier as$table=>$rows){$currentRows=$db->query('SELECT * FROM `'.$table.'`')->fetchAll();$bag=[];foreach($currentRows as$row){$hash=hash('sha256',serialize($row));$bag[$hash]=($bag[$hash]??0)+1;}$exact=in_array($table,['finance_transfer_orders','native_settings_requests','audit_events'],true)||count($currentRows)===count($rows);foreach($rows as$row){$hash=hash('sha256',serialize($row));if(($bag[$hash]??0)<1){$exact=false;break;}$bag[$hash]--;}$check($exact,'actual credit browser preserves each whole earlier row in '.$table);}
    foreach($counts as$table=>$before){$added=$table==='finance_transfer_orders'?1:3;$check((int)$db->query('SELECT COUNT(*) FROM '.$table)->fetchColumn()===$before+$added*count($cases),'actual credit browser creates only its exact reviewed delta in '.$table);}
    foreach($cases as$case){$row=Db::run($db,'SELECT state,total_cents,version FROM finance_transfer_orders WHERE club_id=? AND entry_id=?',[$f['club'],$case['entry']])->fetch();$check($row&&$row['state']==='exported'&&(int)$row['total_cents']===2000&&(int)$row['version']===3&&$f['finance']->entry($case['entry'])['remaining_cents']===2000,'each actual original credit has exactly one exported20 order and remains unpaid by bank evidence');}
    foreach($unlinked as$case)$check((int)Db::run($db,'SELECT COUNT(*) FROM finance_transfer_orders WHERE club_id=? AND entry_id=?',[$f['club'],$case['entry']])->fetchColumn()===0,'actual unlinked original stays readable and creates no bank order or personal payment first');
    $check($db->query('SELECT * FROM native_language_preferences ORDER BY club_id,actor_id')->fetchAll()===$preferences,'credit browser restores exact original personal language choices');foreach($keys as$name=>[$path,$hash])$check(hash_file('sha256',$path)===$hash,'actual credit browser preserves its original private '.$name.' key');
}finally{foreach($browser['servers']as[$process,$log]){proc_terminate($process);proc_close($process);fclose($log);}}
